# Build the transformed grid from the three colored seed patterns.
H,W=26,22
g=[[8]*W for _ in range(H)]
# panel A: rows 2..10, cols 3..8; seed pattern anchored top-right
A=[[0,1,0],[1,0,1],[1,1,0]]
for r in range(2,11):
    for c in range(3,9):
        g[r][c]=A[(r-2)%3][(c-6)%3]
# panel B: rows 4..11, cols 13..18; seed pattern anchored bottom-left
B=[[4,0],[4,4]]
for r in range(4,12):
    for c in range(13,19):
        g[r][c]=B[(r-10)%2][(c-13)%2]
# panel C: rows 16..21, cols 3..10; pattern anchored bottom-right
C=[[3,0,3,3],[0,3,0,3],[3,3,0,3]]
for r in range(16,22):
    for c in range(3,11):
        g[r][c]=C[(r-19)%3][(c-7)%4]
print('\n'.join(' '.join(map(str,row)) for row in g))
